responseSchemaJson:
{
  "type": "object",
  "description": "知识记录大师的核心数据结构。旨在根据用户指令，提炼并结构化信息为多个可独立保存的知识条目。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "knowledgeRecording": {
      "type": "object",
      "description": "包含所有生成知识条目的模块。",
      "properties": {
        "entries": {
          "type": "array",
          "description": "根据用户指令生成的一个或多个独立知识条目的数组。",
          "items": {
            "type": "object",
            "description": "代表一个独立的知识条目。",
            "properties": {
              "name": {
                "type": "string",
                "description": "此知识条目的核心名称或标题。"
              },
              "category": {
                "type": "string",
                "description": "此知识条目所属的分类名称。"
              },
              "notes": {
                "type": "string",
                "description": "此知识条目的详细注释或核心内容文本。"
              }
            },
            "required": [
              "name",
              "category",
              "notes"
            ],
            "propertyOrdering": [
              "name",
              "category",
              "notes"
            ]
          }
        }
      },
      "required": [
        "entries"
      ],
      "propertyOrdering": [
        "entries"
      ]
    },
    "test": {
      "type": "object",
      "description": "[测试模块] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "knowledgeRecording",
    "test"
  ],
  "propertyOrdering": [
    "knowledgeRecording",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const data = JSON.parse(jsonString);
const actions = data.knowledgeRecording.entries.map(e => ({
    type: 'description',
    content: `【知识条目: ${e.name}】\n分类: ${e.category}\n内容: ${e.notes}`
}));
return { processedTurnActions: actions, originalData: data };
